"answer": 1,
"explanation": "エンタープライズアーキテクチャ（EA）は、組織全体の業務・情報・システム・技術を統合的・体系的に可視化・整理し、あるべき姿（To-Be）と現状（As-Is）を比較しながら最適化を図るフレームワーク。政府・省庁でも活用されている。\n\nA：これはBPR（Business Process Re-engineering：業務プロセス再設計）の説明。\nC：情報セキュリティの設計・管理フレームワークの説明。ISMSやゼロトラストアーキテクチャに近い概念。\nD：製品アーキテクチャの標準化はEAとは異なる概念。TOGAF等のEAフレームワークは業種横断的なガイドライン。\n\n【頻出】EA・BPR・ERPの違いは頻出。EAは「設計・可視化の枠組み」、BPRは「業務プロセスの根本的再設計」、ERPは「業務統合システム」。\n【混同注意】EAの4層（ビジネス・データ・アプリケーション・テクノロジー）を整理しておくと、関連問題に対応しやすい。"
