"explanation": "BPRは「ゼロベースからの抜本的な業務再設計」であり、少しずつ改善するカイゼン（継続的改善）とは根本的に異なるアプローチである。カイゼンは日本発の継続的・漸進的改善手法（TQC・トヨタ生産方式由来）。\n\nA：正しい。BPRは「劇的（ドラマチック）な改善」を特徴とし、現行プロセスへの固執を捨ててゼロから再設計する。\nB：正しい。1993年にハマー＆チャンピーの著書「Reengineering the Corporation」で広く普及した。\nD：正しい。ITを業務変革の手段として積極活用する点がBPRの特徴の一つ。\n\n【頻出】BPRと継続的改善（カイゼン・PDCA）の対比は頻出。BPRは「断続的・革命的」、カイゼンは「連続的・漸進的」。\n【混同注意】BPRとERPを組み合わせて導入するケースが多いため、両者の目的の違いを整理しておくこと。"
