"コンテナ型仮想化は、各コンテナが独立したOSカーネルを持つため、仮想マシンよりも多くのリソースを消費する。",
"ホスト型仮想化は、ハイパーバイザーが物理マシンのハードウェアに直接アクセスするため、ハイパーバイザー型より高い性能を発揮する。",
