"取引データをブロックに格納してチェーン状に連結し、分散したノードで共有することで改ざん耐性を実現する技術である。",
"暗号化されたデータを一方向に変換し元のデータに戻せない特性を持つため、パスワード管理にのみ使用される技術である。",
