"クイックソートは基準値（ピボット）を選んでデータを分割しながら整列するアルゴリズムであり、平均計算量はO(n log n)である。",
"マージソートはデータを分割して再帰的に整列・統合するアルゴリズムであり、最悪計算量はO(n²)である。",
