"explanation": "ISO/IEC 25010（SQuaRE：Systems and software Quality Requirements and Evaluation）はソフトウェア製品品質の特性として「機能適合性・性能効率性・互換性・使用性・信頼性・セキュリティ・保守性・移植性」の8つを定義している。旧JIS X 0129-1（ISO/IEC 9126）の後継規格。\n\nB：コストと納期の2軸のみによる評価はISO/IEC 25010の内容と大きく異なる。品質特性は多次元的に定義されている。\nC：ISO/IEC 25010は開発手法に依存せず、ウォーターフォール・アジャイルを問わず適用可能な製品品質評価規格。\nD：情報セキュリティのみを対象とした規格はISMS（ISO/IEC 27001）。ISO/IEC 25010はセキュリティを含む8特性全体を対象とした製品品質規格であり、27001とは目的・対象が異なる。\n\n【頻出】ISO/IEC 25010の8品質特性の名称はITパスポートで頻出。特に「使用性（ユーザビリティ）」「信頼性」「保守性」「セキュリティ」の定義と対策の関係が出題される。\n【混同注意】ISO/IEC 25010（ソフトウェア製品品質）とISO/IEC 27001（情報セキュリティ管理システム）は対象・目的が異なる別規格。番号（25010と27001）を混同しないこと。"
