"ネットワークの内外を問わず、すべてのアクセスを常に検証・認証し、信頼を前提としないセキュリティの考え方である。",
"ゼロコストでセキュリティ対策を実現するための手法であり、高価なハードウェアアプライアンスへの依存をゼロにする概念である。",
