"explanation": "自然言語処理（NLP：Natural Language Processing）はコンピュータが人間の言語（テキスト・音声）を理解・生成・分析する技術。感情分析（センチメント分析）は顧客レビューやSNS投稿の文章をポジティブ・ネガティブ・中立に分類するNLPの典型的な応用例。他の応用例として機械翻訳・文章要約・質問応答・チャットボット・音声認識がある。\n\nA：カメラ映像から製品の外観を自動判定するのはコンピュータビジョン（画像認識）の応用例。NLPとは異なるAI技術領域。\nB：センサーの数値データから異常を検知するのは異常検知・機械学習（時系列分析・統計的手法）の応用例。NLPではない。\nD：交通量データから最適ルートを算出するのはグラフアルゴリズム（ダイクストラ法等）・リアルタイムデータ処理の応用例。NLPではない。\n\n【頻出】NLP（テキスト・音声処理）・コンピュータビジョン（画像・動画処理）・音声認識・強化学習の応用領域の区別は頻出。\n【混同注意】AIの応用技術をどの「センシングデータ（文字・画像・数値・音声）」を処理するかで分類すると整理しやすい。NLPはテキストと音声言語、コンピュータビジョンは画像と映像を対象とする。"
