"在庫回転率は「平均在庫高 ÷ 売上原価」で計算し、値が高いほど在庫が長期間倉庫に保管されていることを示す。",
"在庫回転率は「自己資本 ÷ 平均在庫高」で計算し、企業の財務安全性と在庫管理の効率を同時に示す指標である。",
