"explanation": "コミュニケーション経路数＝n×(n−1)÷2（nはメンバー数）。例：5人では5×4÷2＝10本、10人では10×9÷2＝45本。メンバーが増えると経路数が二次関数的に増加するため、大規模プロジェクトでは意思疎通が急速に複雑化する。PMBOKでも重要な管理概念。\n\nB：n²では5人で25本となるが、正しい計算はn×(n−1)÷2＝10本。n²の計算式は誤り。\nC：2名のとき経路数＝1本、4名のとき＝6本であり、4名に倍増しても経路数は6倍に増加（2倍ではない）。\nD：コミュニケーション経路数はメンバー数に依存して変化する（二次関数的増加）。一定ではない。\n\n【頻出】コミュニケーション経路数の計算式n(n-1)/2と、メンバー増加による経路数の急増（プロジェクト規模管理の観点）は計算問題として頻出。\n【混同注意】「5人のプロジェクトで1人追加して6人になるとき、経路は何本増えるか」という問い：5本増加（6人＝15本、5人＝10本、差＝5本）。追加されたメンバーが既存メンバー全員と通信経路を持つため、n人いれば(n−1)本増加する。"
