"answer": 1,
"explanation": "DevSecOpsはDevOps（開発と運用の統合）にセキュリティ（Sec）を加えた概念。「Shift Left（左シフト）」として、セキュリティ対策を開発プロセスの後半ではなく最初期（設計・コーディング段階）から組み込む。SAST（静的解析）・DAST（動的解析）・SCA（ソフトウェア依存関係の脆弱性チェック）をCI/CDパイプラインに自動統合する。\n\nA：セキュリティ審査をリリース直前のみに実施するのは従来型の開発プロセスの問題点であり、DevSecOpsはこれを解消するために生まれた概念。\nC：DevSecOpsは開発者・運用者・セキュリティ専門家が協力するアプローチであり、アジャイル開発との組み合わせが一般的（アジャイルのスプリントにセキュリティタスクを組み込む）。\nD：DevSecOpsではSAST・DASTなどセキュリティテストの自動化はCI/CDパイプラインへの統合の重要な要素であり、「自動化を含まない」は誤り。\n\n【頻出】DevSecOpsの「Shift Left（早期セキュリティ対応）」概念とSAST・DAST・SCAの役割は近年の頻出トレンド。\n【混同注意】DevOps（Dev＋Ops）とDevSecOps（Dev＋Sec＋Ops）の違いは「セキュリティをプロセスに統合するかどうか」。後者では開発者もセキュリティ意識を持って実装する「セキュリティの民主化」が重要。"
