"answer": 3,
"explanation": "現在も多くの産業用ロボットはあらかじめ決められた動作プログラム（ティーチング・プレイバック方式等）によって制御されており、「すべてAI完全自律型」という記述は誤り。AIを活用した自律型ロボットの開発は進んでいるが、従来型の決定論的制御システムも広く活用されている。\n\nA：正しい。産業用ロボット（垂直多関節ロボット等）は自動車・電子機器製造ラインで広く活用されており、安川電機・ファナック・川崎重工等が主要メーカー。\nB：正しい。農業での農薬散布・生育監視、物流での配送（ドローン配達）、橋梁・電力設備の点検、災害現場の映像取得などで実用化が進んでいる。\nC：正しい。協働ロボット（Collaborative Robot：Cobot）はUR（Universal Robots）・ファナックCR等が代表例。人と安全に共存作業できる設計が特徴。\n\n【頻出】産業用ロボット・協働ロボット・自律移動ロボット（AMR）・ドローンの技術的特徴と応用分野の違いはITパスポートの新技術領域として出題頻度が増加している。\n【混同注意】自動化（Automation：決められた手順の繰り返し）と自律化（Autonomy：環境認識・判断・行動の自己決定）は異なるレベルの技術。多くの産業用ロボットは自動化であり、完全自律ではない。"
