"仮想記憶は補助記憶装置（HDDやSSD）の一部を主記憶の拡張として使用する技術であり、物理メモリより大きなアドレス空間をプログラムに提供できる。",
"仮想記憶を使用すると物理メモリを増設した場合と完全に同等の性能が得られるため、メモリ増設は不要となる。",
