"スマートフォンを使ったQRコード決済・モバイルバンキング・ロボアドバイザーによる自動投資管理はフィンテックの代表的な応用例である。",
"フィンテック企業の参入により金融サービスのデジタル化が進んでいるが、既存の銀行・保険会社はフィンテックの影響を受けないとされている。",
"ブロックチェーン技術を活用した仮想通貨・暗号資産・スマートコントラクトもフィンテックの領域に含まれる。"
