"explanation": "IPv6アドレスは128ビット（16バイト）で構成され、16ビットずつ8ブロックに分けてコロン（:）区切りの16進数で表記する（例：2001:0db8:0000:0000:0000:0000:0000:0001）。連続するゼロブロックは「::」で省略できる。IPv4の32ビット（約43億アドレス）の枯渇対策として設計された。\n\nA：32ビット・ドット区切り10進数4オクテットはIPv4アドレスの説明。\nC：IPv6は128ビットであり、IPv4の32ビットとは長さが異なる。表記方法だけでなくアドレス長自体が異なる。\nD：64ビット・ハイフン区切りというフォーマットはIPv6の定義と一致しない。IPv6のアドレス長は128ビット。\n\n【頻出】IPv4（32ビット・ドット10進）とIPv6（128ビット・コロン16進）のアドレス長と表記方法の違いは毎回出題される。IPv6への移行理由（IPv4アドレス枯渇）もセットで覚える。\n【混同注意】IPv6の「::」省略記法は連続する「0000:0000...」ブロックを一箇所だけ省略できる。例：2001:db8::1は2001:0db8:0000:0000:0000:0000:0000:0001の省略形。"
