"explanation": "IoTゲートウェイはBluetooth・ZigBee・LoRaWAN等の近距離・低消費電力プロトコルを使うIoTデバイスと、TCP/IPベースのインターネット・クラウドとの間でプロトコル変換・データ集約・エッジ処理・セキュリティ確保を担う中継装置。デバイスが直接インターネットに接続できない場合のブリッジとして機能する。\n\nA：無線充電装置はワイヤレス電力伝送（Qi等）の技術であり、ゲートウェイの役割ではない。\nC：データをリアルタイムで可視化するダッシュボードアプリはBIツールやIoTプラットフォームのUI機能であり、ゲートウェイの機能ではない。\nD：クラウドAIモデルの管理・更新はMLOps（Machine Learning Operations）基盤の役割であり、IoTゲートウェイの機能とは異なる。\n\n【頻出】IoTシステムの構成（センサー/デバイス→ゲートウェイ→クラウド/サーバ）の各コンポーネントの役割と、ゲートウェイで行われるエッジ処理の意義は頻出。\n【混同注意】ネットワークのゲートウェイ（異なるネットワーク間の出入り口・デフォルトゲートウェイ）とIoTゲートウェイはどちらも「異なるネットワーク間を接続する中継点」という共通概念だが、IoTゲートウェイはプロトコル変換機能をより重視する。"
