"answer": 0,
"explanation": "ポートスキャンは対象ホストのどのポートが開いているか（サービスが動作しているか）をネットワーク経由で調査する技術。セキュリティ担当者が自社システムの脆弱性調査に使うほか、攻撃者が攻撃対象の調査（偵察）にも使用する。Nmapが代表的なポートスキャンツール。許可なく他者のシステムにポートスキャンを行うことは不正アクセス禁止法等に抵触しうる。\n\nB：大量HTTPリクエストを送信する負荷テストはApache JMeter・Locust等のロードテストツールの機能説明。\nC：ネットワーク上のパケットをキャプチャ・解析するのはパケットキャプチャ（スニファ）技術。Wiresharkが代表例。\nD：マルウェアを検出するためのシステムスキャンはウイルス対策ソフト（アンチウイルス）のフルスキャン機能の説明。\n\n【頻出】ポートスキャン・パケットキャプチャ・脆弱性スキャン・ペネトレーションテストのセキュリティ診断ツール・手法の違いは頻出。\n【混同注意】ポートスキャン（どのポートが開いているかを調査）とパケットキャプチャ（流れているデータの内容を取得）は異なる技術。両方を組み合わせてネットワーク調査が行われる場合がある。"
