"大量のデータで事前学習済みのモデルを、少量のデータで特定のタスクに応用することで効率的に高性能なモデルを構築する手法である。",
"転移学習はデータを他の組織に転送・共有することでモデルの精度を向上させるデータ共有の仕組みである。",
