"answer": 1,
"explanation": "ハイブリッドクラウドはオンプレミス（自社データセンター）とパブリッククラウドを専用線またはVPNで接続し、連携させる構成。機密性の高いデータや既存のレガシーシステムをオンプレミスで維持しつつ、需要変動への対応や新サービス開発にクラウドの弾力性を活用できるメリットがある。\n\nA：複数の異なるクラウドプロバイダーを組み合わせて使う構成はマルチクラウド（Multi-Cloud）の説明。ハイブリッドクラウドはオンプレミスとクラウドの組み合わせを指す。\nC：単一ベンダーのパブリック・プライベートクラウドを両方契約しても、オンプレミスが含まれなければハイブリッドクラウドとは呼ばない場合が多い（定義によって異なる場合もある）。一般的なハイブリッドクラウドはオンプレミスとパブリッククラウドの組み合わせを指す。\nD：ハイブリッドクラウドは常に低コストとは限らない。ネットワーク接続費用・管理複雑性の増加・二重管理コスト等が発生する場合もあり、TCOの比較が必要。\n\n【頻出】オンプレミス・パブリッククラウド・プライベートクラウド・ハイブリッドクラウド・マルチクラウドの定義と特徴の違いは頻出。\n【混同注意】ハイブリッドクラウド（オンプレミス＋クラウド）とマルチクラウド（複数クラウドプロバイダーの組み合わせ）は混同されやすい概念。どちらも「複数の環境を使う」が組み合わせの対象が異なる。"
