"ステークホルダー分析では、影響力と関心度の2軸でステークホルダーをマッピングし、コミュニケーション戦略を策定することが一般的である。",
"ステークホルダーマネジメントは全ステークホルダーに対して全く同一の情報を同じ頻度で提供することが唯一の正解である。",
