"explanation": "サービスカタログ（Service Catalog）はITILのサービス設計フェーズで定義される、IT部門が顧客・エンドユーザーに提供するすべてのサービスの一覧。各サービスについて内容・品質水準（SLA）・申請方法・承認フロー・料金等を記載する。利用者向けの「ビジネスサービスカタログ」と技術的な詳細を含む「テクニカルサービスカタログ」の2層で構成されることが多い。\n\nA：過去のインシデントと解決方法を蓄積したのはナレッジベース（Known Error Database含む）の説明。サービスカタログとは異なる管理ツール。\nC：ハードウェア・ソフトウェアの構成情報を管理するのはCMDB（Configuration Management Database）の説明。サービスカタログはサービスの内容・条件を記載するもので構成情報の管理ではない。\nD：ベンダーのサービス価格比較・調達支援はe調達ツールや購買システムの機能。サービスカタログは内部・外部の提供サービスの一覧であり価格比較ツールではない。\n\n【頻出】ITILにおけるサービスカタログ管理プロセス（サービスの登録・更新・廃止の管理）とSLAとの関連、ビジネスサービスカタログとテクニカルサービスカタログの違いは頻出。\n【混同注意】サービスカタログ（提供できるサービスの一覧）とサービスポートフォリオ（提供中・開発中・廃止済みすべてのサービスを管理するより広い概念）の違いを理解する。"
