"Thunderbolt端子はIntelとAppleが共同開発したインターフェースであるが、USB Type-Cとは物理コネクタ形状が全く異なる。",
"PCIeはコンピュータの内部バス規格であり、外部接続インターフェースとして使用されるUSBやHDMIとは全く異なる用途のみに限定される。"
