"answer": 0,
"explanation": "USB（Universal Serial Bus）はシリアル伝送方式のインターフェース規格であり、USB Type-Cは最新のコネクタ規格で表裏なく挿せる形状・電力供給（USB Power Delivery：最大240W）・データ転送（USB 3.2/USB4）・映像出力（Alt Mode）を1つのコネクタで提供できる汎用インターフェース。\n\nB：HDMIはデジタル映像と音声を同時に伝送できるインターフェース。「音声に対応していない」は誤り。最大8チャンネルの音声も伝送できる点がDisplayPortと類似している。\nC：Thunderbolt（Ver.3以降）はUSB Type-CコネクタをThunderbolt信号で使用する規格であり、物理的な形状はUSB Type-Cと同一。Thunderbolt端子とUSB Type-Cが同じ形状であることは重要な知識。\nD：PCIeはコンピュータのマザーボード上での内部バス規格（グラフィックカード・NVMe SSD等の接続に使用）だが、外付けGPU（eGPU）等の外部接続にも活用されており「外部に全く使われない」は誤り。\n\n【頻出】USB Type-A/B/C・USB規格世代（2.0/3.0/3.1/4）・HDMI・DisplayPort・Thunderbolt・PCIe等の主要インターフェースの特徴と用途の違いは頻出。\n【混同注意】Thunderbolt 3/4はUSB Type-Cコネクタを使用するが、すべてのUSB Type-CポートがThunderboltに対応するわけではない。Thunderbolt対応ポートには稲妻マークが付いていることが多い。"
