"explanation": "プロジェクト終結（Closing）フェーズの主要活動は①成果物の正式な引き渡し・顧客による受け入れ確認②契約の正式なクローズ（外部ベンダーとの契約終了手続き）③プロジェクトで得た教訓（Lessons Learned）の文書化・組織プロセス資産への追加④チームメンバー・設備等のリソース解放⑤プロジェクト記録・文書のアーカイブ作成⑥最終報告書の作成・ステークホルダーへの報告。\n\nA：スコープ・コスト・スケジュールのベースライン設定と変更管理プロセスの確立は計画（Planning）フェーズの活動。\nC：プロジェクトのフィジビリティスタディ（実現可能性調査）は立上げ（Initiating）またはその前段階（企画フェーズ）の活動。\nD：スプリントゴールに向けた技術タスクへの分解・見積もりはアジャイル開発のスプリントプランニングの活動。プロジェクト終結とは無関係。\n\n【頻出】PMBOKのプロジェクトライフサイクル（立上げ→計画→実行→監視・コントロール→終結）の各フェーズの主要活動と成果物は頻出。\n【混同注意】教訓の文書化（Lessons Learned）は終結フェーズの重要な成果物であり、次のプロジェクトへの組織的学習として活用される。「終わったらそれで完了」ではなく、振り返りと知識の蓄積が終結フェーズの本質的価値。"
