"explanation": "モノリシックカーネル（Linux・Unix等）はデバイスドライバ・ファイルシステム・ネットワークスタック等の多くの機能をカーネル空間に一体化した設計。カーネル空間内での直接呼び出しにより高速に動作するが、一部のコードのバグがカーネル全体をクラッシュさせるリスクがある。マイクロカーネル（QNX・Mach等）は最小限の機能のみカーネル空間に置き、他のサービスをユーザー空間で動作させることで安定性・モジュール性を高めるが、ユーザー空間とカーネル空間の間のメッセージパッシングによりオーバーヘッドが生じる。\n\nA：「すべての機能をカーネル空間に集約した設計」はモノリシックカーネルの説明。マイクロカーネルは最小限の機能（IPC・基本的なメモリ管理・スケジューリング等）のみをカーネル空間に置く。\nC：マイクロカーネルはメッセージパッシングのオーバーヘッドにより一般的にモノリシックカーネルより遅い場合が多い。LinuxはモノリシックカーネルであるにもかかわらずAndroid・多数のサーバで広く使われており、「すべての現代的なOSがマイクロカーネルを採用」は誤り。\nD：モノリシックカーネルはカーネル空間で動作し、マイクロカーネルはユーザー空間に多くのサービスを移している。システムコールの処理方式は根本的に異なる。\n\n【頻出】モノリシックカーネル（高速・バグの影響大）とマイクロカーネル（安定・モジュール性高・オーバーヘッド有）のトレードオフは出題される。\n【混同注意】ハイブリッドカーネル（WindowsNT・macOS XNU等）はモノリシックとマイクロカーネルの中間的設計を採用しており、純粋なマイクロカーネルではない点も重要。"
