"SDGsは日本政府が独自に策定した国内の環境保全目標であり、国連が定めた17の持続可能な開発目標とは別の取り組みである。",
"コーポレートガバナンスとは、経営者が株主の監視を受けずに経営判断を自由に行える仕組みを強化するための制度である。"
