"answer": 1,
"explanation": "ESG投資は機関投資家・年金基金等が企業評価において財務業績だけでなくESG（環境：気候変動対応・資源効率、社会：人権・労働慣行・多様性、ガバナンス：取締役会構成・透明性・腐敗防止）を評価軸に加える投資手法。ESGスコアが高い企業は長期的なリスクが低く持続可能な価値創造が期待できるという考えに基づく。\n\nA：CSR（企業の社会的責任）は「株主利益最大化のみ」という考え方とは異なり、株主・従業員・顧客・地域社会・環境等のすべてのステークホルダーに対する責任を果たすことを求める概念。\nC：SDGs（Sustainable Development Goals：持続可能な開発目標）は2015年の国連総会で採択された国際目標であり、日本政府独自の取り組みではない。17のゴール・169のターゲットで構成される。\nD：コーポレートガバナンス（企業統治）は経営者の行動を株主・取締役会・監査機関等が適切に監督し、透明性・説明責任・適切な経営判断を確保する仕組み。「経営者が株主の監視を受けずに自由に行動する」のはコーポレートガバナンスの目的と逆。\n\n【頻出】ESG投資・CSR・SDGs・コーポレートガバナンス・サステナビリティ経営の関係と違いはストラテジ系の頻出トレンド。\n【混同注意】ESGは投資判断の軸（外部の投資家視点）、CSRは企業が自発的に社会・環境への責任を果たす活動（企業の自律的取り組み）、SDGsは達成すべき国際目標（フレームワーク）という役割の違いを整理する。"
