"answer": 1,
"explanation": "フィーチャーフラグ（Feature Flag・Feature Toggle）はコードに条件分岐（if flag.isEnabled）を追加し、設定変更だけで特定の機能をランタイムに有効化・無効化できる仕組み。主な用途は①カナリアリリース（一部ユーザーにのみ新機能を公開してリスクを段階的に評価）②A/Bテスト（複数の機能バリアントを比較検証）③緊急キルスイッチ（本番で問題が発生した際に再デプロイなしで機能を即時無効化）④開発中の機能を本番コードに含めたまま隠す（トランクベース開発との組み合わせ）。LaunchDarkly・CloudBees Feature Management等のサービスが存在する。\n\nA：フィーチャーフラグはGitのブランチ戦略ではなく、コードの条件分岐による機能切り替えの仕組み。フィーチャーブランチ（機能ごとのGitブランチ）とは別の概念。\nC：本番のバグを自動修正するAI機能はフィーチャーフラグの説明ではない。AIコード修正はGitHub Copilot等の別の技術。\nD：Dockerイメージのバージョン管理はDockerタグ・イメージレジストリの機能であり、フィーチャーフラグとは無関係。\n\n【頻出】フィーチャーフラグのカナリアリリース（段階的ロールアウト）・ブルーグリーンデプロイメント・A/Bテストへの活用と、トランクベース開発（常にメインブランチに統合）との組み合わせは近年の頻出トレンド。\n【混同注意】カナリアリリース（一部ユーザーに段階的公開）とブルーグリーンデプロイメント（2つの本番環境を用意してスイッチング）は異なるリリース戦略。どちらもフィーチャーフラグと組み合わせて使われる場合がある。"
