"explanation": "1年間の総時間＝24時間×365日＝8,760時間。稼働率99.9%のダウンタイム＝8,760時間×（1−0.999）＝8,760時間×0.001＝8.76時間。月換算では約43.8分/月に相当する。よって約8.76時間が正解。\n\nB（87.6時間）：稼働率99.0%（ダウン率1%）に相当する計算。99.9%と99.0%の1桁の違いでダウンタイムが10倍になる点が重要。\nC（0.876時間）：稼働率99.99%（ダウン率0.01%：いわゆる「フォーナイン」）に相当するダウンタイム。\nD（876時間）：稼働率90%（ダウン率10%）に相当する計算。\n\n【頻出】稼働率の計算とSLAでの各稼働率水準（99%・99.9%・99.99%・99.999%）のダウンタイム換算は計算問題として頻出。「ナイン」の個数とダウンタイムの対応（99.9%＝年8.76時間、99.99%＝年52.6分）を覚えておく。\n【混同注意】稼働率の小数点位置（99.9%と99.99%の違い：ダウンタイムが10倍差）を計算問題で見落とさないよう注意。ダウン率＝1−稼働率で計算してから年間総時間に掛けるステップを確実に行う。"
