"choices": [
"オブザーバビリティとはシステムの外部出力（ログ・メトリクス・トレース）を収集・分析することで、システムの内部状態を推測・理解できる度合いを表す概念である。",
"オブザーバビリティとは監視カメラやセンサーを使って物理的なデータセンターのセキュリティ状況を把握するための物理セキュリティ管理の概念である。",
"オブザーバビリティはシステムの監視アラートをオペレーターに通知するだけの単純な死活監視（ピン監視）と同義である。",
"オブザーバビリティはデータサイエンスにおける探索的データ分析（EDA）の別称であり、データの統計的分布を可視化する手法のことである。"
],
"answer": 0,
"explanation": "オブザーバビリティ（Observability：可観測性）は制御理論に由来する概念で、ソフトウェアエンジニアリングでは「システムの外部出力（テレメトリデータ）からシステムの内部状態を推測・理解できる度合い」を指す。3つの柱はLogs（ログ：イベントの時系列記録）・Metrics（メトリクス：定量的な数値データ）・Traces（分散トレーシング：マイクロサービス間のリクエスト追跡）。OpenTelemetry・Datadog・Grafana等が代表的なツール。\n\nB：物理セキュリティのカメラ・センサー監視とオブザーバビリティは全く別の概念。ソフトウェアシステムのオブザーバビリティは仮想的なシステムの内部状態の可視化に関する概念。\nC：死活監視（ピン監視：システムが動いているかのYES/NO確認）はオブザーバビリティの最も基本的な要素に過ぎない。オブザーバビリティは「なぜ問題が起きているか」を理解するための深い洞察力を提供する概念であり、単純なアラートとは次元が異なる。\nD：EDA（探索的データ分析）はデータサイエンスのデータ理解フェーズの手法。オブザーバビリティはシステム運用・SRE（Site Reliability Engineering）の概念であり、別の領域。\n\n【頻出】オブザーバビリティの3本柱（Logs・Metrics・Traces）とSRE（サイト信頼性エンジニアリング）での活用、従来の監視（Monitoring）との違いは近年の頻出トレンド。\n【混同注意】モニタリング（Monitoring：既知の問題を事前定義したメトリクスで検知）とオブザーバビリティ（Observability：未知の問題でも外部出力から原因を推測できる能力）は目的が異なる。前者は「何かがおかしい」を検知し、後者は「なぜおかしいか」を理解するための能力を指す。"
