"ベロシティとはWebアプリケーションのページ読み込み速度を測定するフロントエンドパフォーマンス指標であり、Googleのツールで測定できる。",
"ベロシティとはプロジェクト全体の予算消化速度を示す財務指標であり、EVM（アーンドバリューマネジメント）のコスト効率指数と同義である。",
"ベロシティとはスクラムマスターが各スプリントでチームに割り当てる作業量の上限を定める権限のある指標であり、外部から設定・変更できる。"
