"answer": 0,
"explanation": "マルチテナント（Multi-Tenant）アーキテクチャは複数の顧客（テナント）が同一のソフトウェアインスタンス・インフラを論理的に分離した状態で共有して使用する設計。各テナントのデータは論理的に分離されており、他テナントからはアクセスできないが、物理的なリソースは共有される。Salesforce・Slack・GitHub等のSaaSの大多数が採用しており、リソース共有によるコスト効率の高さが最大のメリット。\n\nB：複数のクラウドプロバイダーを使うのはマルチクラウドの説明。マルチテナントは複数の「顧客（テナント）」が単一のシステムを共有する概念であり、クラウドプロバイダーの複数使用とは別の概念。\nC：「各テナント専用のサーバ・DBを個別に用意する」のはシングルテナント（専有型）またはSaaS over dedicated infrastructure（専有クラウド）の説明。マルチテナントはリソースを共有するため低コスト、シングルテナントは専有のため高コストというトレードオフがある。\nD：マルチテナントはOSS・商用を問わずアーキテクチャの設計選択の問題。Salesforce（商用）・GitHub（商用）も典型的なマルチテナントSaaSを採用している。\n\n【頻出】マルチテナント（共有型：コスト効率高・テナント間の論理分離）とシングルテナント（専有型：完全分離・高コスト・カスタマイズ自由）のトレードオフは頻出。\n【混同注意】SaaSのマルチテナント設計でのテナント分離方法（共有DBの行レベル分離・スキーマ分離・DB分離）はセキュリティ・パフォーマンスのトレードオフで設計が異なる。テナント分離が不十分だとデータ漏洩リスクが生じる。"
