"answer": 1,
"explanation": "意匠権は工業デザイン・製品の外観（形状・模様・色彩またはその組み合わせで視覚を通じて美感を起こさせるもの）を保護する産業財産権。特許庁に意匠登録出願し審査を経て登録されることで権利が発生する。2020年改正意匠法により、内装デザイン・画像（UI/UX）・建築物の外観・外観が部分的に変化する意匠等も保護対象に追加された。\n\nA：「技術的なアイデア・発明・機能・構造」を保護するのは特許権（特許法）の説明。意匠権は外観の「見た目・デザイン」を保護する。\nC：意匠権の存続期間は意匠法第21条（2020年改正）により「意匠登録出願の日から20年（旧法は登録から20年）」に変更された。「10年・更新可能」は誤り。\nD：登録なしに自動発生する無方式主義の権利は著作権。意匠権は出願・審査・登録という方式主義によって発生する産業財産権であり、自動発生しない。\n\n【頻出】意匠権（外観デザイン・特許庁登録・20年）と特許権（発明・特許庁登録・20年）・商標権（ブランド・特許庁登録・10年更新可能）の保護対象・期間の違いは産業財産権の頻出比較問題。\n【混同注意】2020年意匠法改正でGUI（グラフィカルユーザーインターフェース）の画像デザインやアプリの内装デザインも意匠権の保護対象になった点はITに関連する改正として出題される可能性がある。"
