"answer": 1,
"explanation": "ソフトウェア品質保証（QA：Quality Assurance）はテスト実施だけでなく、①品質計画（品質目標の設定・テスト計画）②プロセス改善（開発プロセス自体の品質向上）③テスト設計・実施（単体/結合/システム/受け入れテスト）④欠陥管理（バグトラッキング・根本原因分析）⑤品質メトリクスの収集・分析（欠陥密度・カバレッジ等）を開発ライフサイクル全体を通じて行う体系的な活動。テスト（QC：Quality Control）はQAの一部。\n\nA：品質保証はリリース直前のテストのみに限定されない。「シフトレフト（Shift Left）」の考え方では、品質活動を開発の最初期（要件定義・設計段階）から開始することで後工程での手戻りコストを削減できる。\nC：QCサークルは製造業の現場改善活動の一形態。ソフトウェアQAは専門のQAエンジニアやテストチームが組織的に取り組む活動であり、QCサークルのみで実施されるものではない。\nD：品質保証の強化は短期的にコストを増加させる場合があるが、早期に欠陥を発見・修正することで後工程・本番でのバグ修正コスト（一般的に工程が後になるほど修正コストが増大）を削減できる。長期的にはコスト削減・顧客満足向上につながる場合が多い。\n\n【頻出】QA（品質保証：プロセス全体）とQC（品質管理：テスト等の欠陥検出）の違い、シフトレフトの考え方（早期品質活動）と後工程での欠陥修正コストの増大（バグの修正費用は工程が進むほど指数的に増加）は頻出。\n【混同注意】テスト（実際に動かして欠陥を検出）とレビュー（静的に欠陥を検出）はどちらもQA活動に含まれるが、異なるアプローチ。テストは動的検証、レビューは静的検証という分類を理解する。"
