"explanation": "マルチキャスト（Multicast）は1台の送信元から事前に登録した特定の受信者グループ（マルチキャストグループ：224.0.0.0〜239.255.255.255のIPv4アドレス範囲）に対して同時にデータを送信する通信方式。同一データを複数宛先に送る際に、ユニキャストのような宛先ごとの個別送信と比べて帯域幅を節約できる利点がある。\n\nB：1つの送信元から1つの受信者への通信はユニキャスト（Unicast）の説明。WebブラウジングのHTTP通信はユニキャストの典型例。\nC：ネットワーク上のすべての機器へ一斉送信する方式はブロードキャスト（Broadcast）の説明。ARPリクエスト・DHCPディスカバーがブロードキャストの代表例。\nD：複数の送信元と複数の受信者が任意に通信する方式はP2P（ピアツーピア）通信の概念に近いが、マルチキャストの定義ではない。\n\n【頻出】ユニキャスト（1対1）・マルチキャスト（1対グループ）・ブロードキャスト（1対全体）・エニーキャスト（1対最近接の1）の4通信方式の違いと代表的な使用例は頻出。\n【混同注意】マルチキャストとブロードキャストはどちらも「1対多」だが、マルチキャストはグループメンバーのみに送信し、ブロードキャストはネットワーク内の全ホストに送信する点が異なる。"
