"explanation": "スタックメモリは関数の呼び出しスタックに対応してLIFO方式で自動管理される領域。局所変数・関数パラメータ・戻りアドレス等が格納され、関数終了時に自動解放される。高速・固定サイズ・容量が小さい。ヒープメモリはプログラマ（またはGC）が動的に確保（malloc/new）・解放（free/delete）する自由なメモリ領域。大きなデータ・ライフサイクルが不定のオブジェクト等に使用される。スタックより低速・容量が大きい。\n\nB：「ヒープはコンパイル時固定・高速、スタックは実行時動的・低速」はスタックとヒープの説明が逆。スタックが高速・小容量、ヒープが動的・大容量が正しい特性の対応。\nC：「スタックは大容量・低速、ヒープは関数のローカル変数のみ・高速」もスタックとヒープの特性が逆になっている。\nD：スタックもヒープもRAM（主記憶装置）上に確保される揮発性のメモリ領域。HDDやSSD上の不揮発性ストレージではない。\n\n【頻出】スタック（自動管理・高速・小容量・LIFO・局所変数）とヒープ（手動/GC管理・動的・大容量・オブジェクト）の違い、スタックオーバーフロー（再帰が深くなりすぎてスタック領域を使い果たす）はC言語・Java等のメモリ管理問題として頻出。\n【混同注意】データ構造のスタック（LIFO型の抽象データ構造）とメモリ上のスタック領域（関数呼び出し管理のメモリ）は同じ概念から来ているが異なる文脈で使われる。メモリ上のスタック領域はスタックデータ構造の動作原理を利用して関数呼び出しを管理する。"
