"CI/CDパイプラインはデプロイ後のシステム監視と障害対応のみを自動化する仕組みであり、コードのビルドやテストは含まれない。",
"CI/CDパイプラインは手動によるコードレビューをすべて廃止することが必須要件であり、自動化とプルリクエストレビューは共存できない。",
