"answer": 0,
"explanation": "CI/CDパイプラインの典型的なステージは「コードコミット/プッシュ→ソースコード取得→ビルド（コンパイル）→自動テスト（ユニット・結合）→静的コード解析・セキュリティスキャン（SAST・SCA）→アーティファクト（ビルド成果物）の作成・保存→ステージング/テスト環境へのデプロイ→E2Eテスト・承認→本番環境へのデプロイ」で構成される。各ステージで問題が検出されるとパイプラインが停止して開発者に通知する。\n\nB：CI/CDパイプラインはデプロイ後の監視だけでなく、ビルド・テスト・セキュリティスキャン・デプロイの全工程を自動化することが主目的。デプロイ後の監視はオブザーバビリティツール（Datadog等）が担う別の機能。\nC：CI/CDパイプラインと手動コードレビュー（プルリクエスト）は共存・補完する関係にある。多くのチームでプルリクエストのレビュー承認後にCI/CDパイプラインが自動実行される運用が一般的。\nD：CI/CDは開発手法（アジャイル・ウォーターフォール）を問わず適用できる技術実践。ウォーターフォールでも自動ビルド・テストの自動化の恩恵を受けられる。\n\n【頻出】CI/CDパイプラインの各ステージ（ビルド→テスト→スキャン→デプロイ）の順序と目的、パイプライン失敗時のフィードバックループは頻出。\n【混同注意】CIステージ（コード統合・ビルド・テスト）とCDステージ（デプロイ・リリース）の境界は明確ではなく、ツールや組織によって異なる。GitHub Actions・Jenkins・GitLab CI/CD・CircleCIが代表的なCI/CDツール。"
