"explanation": "AIエージェント（AI Agent）は与えられた目標に向けて計画・推論・ツール使用・行動を自律的に繰り返すAIシステム。LLMを推論エンジンとして、Web検索・コード実行・データベース照会・API呼び出し・ファイル操作等の外部ツールを必要に応じて使用しながら複数ステップのタスクを自律遂行する。AutoGPT・LangChain Agent・OpenAI Function Calling・Claude Tool Use等が代表例。マルチエージェントシステムでは複数エージェントが協力してより複雑なタスクを実行できる。\n\nB：フローチャート型のルールベースチャットボットは従来の決定論的なチャットボット設計。AIエージェントは事前定義シナリオに縛られず、状況に応じて自律的に判断・行動する点が本質的に異なる。\nC：AIチップ（GPU・TPU）の設計・製造はハードウェアエンジニア・半導体設計者の職種説明。AIエージェントはソフトウェア・AI技術の概念であり、ハードウェア設計とは無関係。\nD：AIモデルの評価ベンチマーク自動実行はMLOps・モデル評価パイプラインの機能に近い。AIエージェントはベンチマーク評価の自動化ツールに限定されない幅広い自律タスク遂行の概念。\n\n【頻出】AIエージェントの自律性（計画→実行→観察→再計画のサイクル）とツール使用（Function Calling・Tool Use）の仕組み、RAG・プロンプトエンジニアリング・ファインチューニングとの技術的な位置づけの違いは近年の最頻出AIトレンド。\n【混同注意】シングルエージェント（一つのLLMが全ステップを処理）とマルチエージェント（複数の専門エージェントが協調：AutoGenやLangGraphのグラフ型マルチエージェント）の設計上の違いを理解する。"
