"answer": 0,
"explanation": "イベント駆動アーキテクチャ（EDA）はイベント（在庫切れ・注文確定・ユーザー登録・センサー値の変化等）の発生をトリガーとして関連処理を起動する設計パターン。イベントを生成するProducer・イベントをルーティング・配信するEvent Broker（Apache Kafka・AWS SNS/SQS・RabbitMQ等）・イベントを受信して処理するConsumerの3つのコンポーネントで構成され、非同期メッセージングによりサービス間の疎結合を実現する。マイクロサービス・IoT・リアルタイム処理システムで広く採用される。\n\nB：EDAは非同期通信を主要な通信パターンとして使用するアーキテクチャ。リクエスト・レスポンス型の同期通信はRESTful APIやgRPCが担い、EDAsは補完的に使われる。「同期のみ・非同期を含まない」はEDAの核心的な特徴と矛盾する。\nC：EDAsはモノリシックアプリケーション内でも使用できるが（例：ドメインイベントによる内部コンポーネントの疎結合化）、本来の強みは分散システム・マイクロサービス間の非同期通信での疎結合化であり「分散系に適用困難」は誤り。\nD：OLTPシステム（リアルタイムトランザクション処理）へのEDA適用は可能だが、EDAはOLTP専用ではない。EDAは分析基盤・IoT・ユーザー通知・ワークフロー自動化等、様々な用途に広く使われる。\n\n【頻出】EDAのProducer・Broker・Consumerの役割と非同期メッセージングによる疎結合・スケーラビリティ・耐障害性の向上、Apache Kafkaの役割は近年の分散システム設計の頻出トレンド。\n【混同注意】EDA（イベント駆動）とREST API（リクエスト駆動・同期）は対比的なアーキテクチャパターン。「顧客が注文したら→リアルタイムに在庫・配送・通知システムを呼び出す」場合、REST（同期・強結合）よりEDA（非同期・疎結合）の方が拡張性・障害分離性が高い。"
