"explanation": "AutoML（Automated Machine Learning）は機械学習の開発工程—データ前処理・特徴量選択・モデルアーキテクチャ探索（NAS：Neural Architecture Search）・ハイパーパラメータ最適化（HPO）・アンサンブル手法の選択等—を自動化する技術。データサイエンティストの作業負荷を軽減し、機械学習の専門知識が限られた利用者（市民データサイエンティスト）でも高品質なモデルを構築できるよう民主化を促進する。Google AutoML・DataRobot・H2O AutoML・Azure AutoMLが代表例。\n\nA：産業用自動化ロボット（FA：Factory Automation）の説明。AutoMLはソフトウェア・機械学習の自動化技術であり、物理的なロボットとは無関係。「ML」はMachine Learningの略。\nC：自律移動ロボット（AMR：Autonomous Mobile Robot）のナビゲーション制御の説明。AutoMLはAMRとは全く別の技術領域。\nD：AutoMLはモデル構築の自動化、MLOpsはモデルの運用（デプロイ・監視・再学習）の自動化という異なる領域。DataRobot・H2O.aiはAutoMLツールの代表例であり、MLOpsとは別カテゴリではなく、AutoMLを提供するプラットフォームとして正しい説明。\n\n【頻出】AutoML（モデル構築の自動化）とMLOps（機械学習ライフサイクルの運用管理）の役割の違い、市民データサイエンティスト（専門知識なしにAIを活用できる非専門家）の概念との関連は頻出。\n【混同注意】AutoML（ビルド時の自動化：どのモデルを使うか・パラメータをどう設定するか）とMLOps（ランタイムの自動化：デプロイ・監視・再学習）は機械学習ライフサイクルの異なるフェーズを自動化する技術。どちらも「MLの民主化・効率化」を目指すが、対象フェーズが異なる。"
