"explanation": "ADR（Architecture Decision Record）はMichael Nygardが提案した、ソフトウェアアーキテクチャに関する重要な意思決定を記録する軽量なドキュメント形式。典型的な構成は「タイトル・ステータス（提案/承認/廃止）・コンテキスト（背景・制約）・決定（何を決めたか）・結果（採用した場合の影響）・代替案（検討したが不採用の選択肢）」。設計理由が時間と共に失われる問題（「なぜこの設計にしたか誰も知らない」）を防ぎ、将来のチームメンバーへの知識継承・技術的負債の管理に貢献する。\n\nB：会議の議事録（Minutes of Meeting）はADRとは別の文書形式。ADRは意思決定の記録に特化しており、出席者・日時等の会議事務的情報より「何をなぜ決めたか」の設計根拠を重視する。\nC：インシデント発生時の障害対応手順はインシデントレスポンス計画・Runbook・ポストモーテムの文書。ADRはアーキテクチャの設計意思決定の記録であり、インシデント対応文書とは異なる。\nD：Gitのコミットログ・プルリクエストは変更の履歴を追跡するが、設計決定の「なぜ」という文脈・代替案の検討履歴は一般的に含まれない。ADRはGitリポジトリで管理されることが多いが、Gitの機能名称ではない。\n\n【頻出】ADRの役割（設計決定の文脈・根拠の保存）と技術的負債管理・アーキテクチャガバナンスとの関係、アーキテクチャフィットネス関数（進化的アーキテクチャの適合性評価）との組み合わせは近年の頻出ソフトウェア設計トレンド。\n【混同注意】ADR（アーキテクチャの意思決定記録）とRFC（Request for Comments：設計提案・議論のプロセス：Googleのデザインドックや社内RFC）は関連するが異なる。RFCは決定前の提案・議論、ADRは決定後の記録という時系列の違いがある。"
