"question": "次のア〜エのうち、デジタルビジネスの主要な概念として正しい記述の組み合わせはどれか。\n\nア：プラットフォームビジネスは、複数のユーザーグループ（生産者と消費者等）を結びつけることで価値を生み出すビジネスモデルであり、ネットワーク効果によって規模が大きくなるほど価値が高まる。\nイ：サブスクリプションモデルは製品・サービスを購入するのではなく、一定期間利用する権利を定額で提供するビジネスモデルであり、企業にとっては収益の予測可能性が向上する。\nウ：フリーミアムモデルとは一切の有料プランを持たない完全無料サービスのことであり、収益はすべて広告収入のみで賄われるビジネスモデルである。\nエ：ロングテール戦略とは少数の大ヒット商品のみに集中して在庫・販売リソースを最大投入することで、規模の経済を最大化する販売戦略である。",
