"explanation": "ア：正しい。プラットフォームビジネス（Amazon・Uber・YouTube等）は生産者と消費者を結びつける多面市場の構造を持ち、ネットワーク効果で成長するほど価値が増大する。\nイ：正しい。Spotify・Netflix・Adobe Creative Cloud等のサブスクリプションモデルは定額制で利用権を提供し、MRR（月次経常収益）・ARR（年次経常収益）の予測可能な安定収益を実現する。\nウ：誤り。フリーミアム（Freemium）は基本機能を無料提供し、プレミアム機能（高度な機能・追加容量等）を有料で提供するハイブリッドなビジネスモデル。「完全無料・広告収入のみ」はフリーミアムの定義と異なる。Dropbox・Slack・Spotify（無料/有料プランあり）がフリーミアムの代表例。\nエ：誤り。ロングテール戦略は少数の大ヒット商品（ショートヘッド）だけでなく、多数の少量販売の商品（ロングテール：需要が少ないニッチ商品の積み上げ）の合計で大きな売上を確保するAmazon型の戦略。「少数の大ヒット商品のみに集中」はロングテール戦略と正反対の考え方。\n\n【頻出】プラットフォームビジネス（多面市場・ネットワーク効果）・サブスクリプション（定額制・MRR/ARR）・フリーミアム（無料＋有料プレミアム）・ロングテール（ニッチ商品の積み上げ）の各ビジネスモデルの正確な定義と代表事例はデジタルビジネス戦略の頻出問題。\n【混同注意】フリーミアムと完全無料（ad-supported）モデルの違い：フリーミアムは無料ユーザーを将来の有料転換候補（コンバージョン）として獲得するモデル、広告モデルは無料で使えるが広告主から収益を得るモデルであり、収益源と戦略が異なる。"
